rcVrrpTmpOperationsPriority = MibTableColumn((1, 3, 6, 1, 4, 1, 2272, 1, 206, 1, 1, 7, 1, 6), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 255)).clone(100)).setMaxAccess("readcreate")
